R=240000.0
rows=[]
for raw in ATLAS.split(';'):
    q,r,b=map(int,raw.split(','))
    x,y=R*math.sqrt(3)*(q+r/2),R*1.5*r
    polygon=[[x+R*math.cos(math.pi/6 + math.pi/3*k),y+R*math.sin(math.pi/6+math.pi/3*k)] for k in range(6)]
    rows.append({'id':f'H_{q}_{r}', 'axial':{'q':q,'r':r},'center_m':[x,y], 'polygon_m':polygon,'dominant_biome_id':b})
out=Path(__file__).parents[1]/'data'/'regions_snapshot.json'
out.write_text(json.dumps({'schema_version':'snapshot-1','orientation':'pointy-top','hex_radius_m':R,'world_extent_m':[6400000,8000000],'note':'Snapshot das classes dominantes Codex; use prepare_assets.py para dados integrais','regions':rows},ensure_ascii=False,separators=(',',':')),encoding='utf8')
print('Salvo',len(rows),'regiões em',out,'; H_5_7 bioma=',next(x['dominant_biome_id'] for x in rows if x['id']=='H_5_7'))